var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>();
// "It keeps no state, so a singleton is cheaper"
builder.Services.AddSingleton<PriceService>();
var app = builder.Build();

app.MapGet("/products/{id:int}/price",
    async (int id, PriceService prices) => await prices.GetAsync(id));
app.Run();

public sealed class PriceService(ShopDb db)
{
    // One ShopDb from the root scope, shared by every request
    public async Task<decimal?> GetAsync(int id) =>
        (await db.Products.FindAsync(id))?.Price;
}

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<ShopDb>();
// No longer-lived than its shortest-lived dependency
builder.Services.AddScoped<PriceService>();
var app = builder.Build();

app.MapGet("/products/{id:int}/price",
    async (int id, PriceService prices) => await prices.GetAsync(id));
app.Run();

public sealed class PriceService(ShopDb db)
{
    // A fresh ShopDb per request, disposed when the request ends
    public async Task<decimal?> GetAsync(int id) =>
        (await db.Products.FindAsync(id))?.Price;
}

