using Microsoft.EntityFrameworkCore;

public sealed class SaleExpiry(IServiceScopeFactory scopes) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromMinutes(5));
        while (await timer.WaitForNextTickAsync(ct))
        {
            // One scope per run: a fresh ShopDb, disposed when the run ends
            await using var scope = scopes.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<ShopDb>();
            await db.Products.Where(p => p.SaleEndsAt < DateTime.UtcNow)
                .ExecuteUpdateAsync(s => s.SetProperty(p => p.OnSale, false), ct);
        }
    }
}
